CREATE TABLE [inventory].[StockReservations] (
    [StockReservationId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_StockReservations_Id] DEFAULT NEWSEQUENTIALID(),[ReservationNo] NVARCHAR(50) NOT NULL,[ProductId] UNIQUEIDENTIFIER NOT NULL,[WarehouseId] UNIQUEIDENTIFIER NOT NULL,[ZoneId] UNIQUEIDENTIFIER NULL,[BinId] UNIQUEIDENTIFIER NULL,[BatchNo] NVARCHAR(100) NULL,[SerialNo] NVARCHAR(100) NULL,
    [Quantity] DECIMAL(18,4) NOT NULL,[ReleasedQuantity] DECIMAL(18,4) NOT NULL CONSTRAINT [DF_StockReservations_Released] DEFAULT 0,[ReservationReason] NVARCHAR(250) NOT NULL,[ReferenceType] NVARCHAR(50) NULL,[ReferenceId] UNIQUEIDENTIFIER NULL,[Status] NVARCHAR(20) NOT NULL CONSTRAINT [DF_StockReservations_Status] DEFAULT 'ACTIVE',[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_StockReservations_Created] DEFAULT SYSUTCDATETIME(),[ModifiedOn] DATETIMEOFFSET NULL,[RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_StockReservations] PRIMARY KEY ([StockReservationId]),CONSTRAINT [UQ_StockReservations_No] UNIQUE ([ReservationNo]),CONSTRAINT [FK_StockReservations_Product] FOREIGN KEY ([ProductId]) REFERENCES [master].[Products]([ProductId]),CONSTRAINT [FK_StockReservations_Warehouse] FOREIGN KEY ([WarehouseId]) REFERENCES [inventory].[Warehouses]([WarehouseId]),CONSTRAINT [FK_StockReservations_Zone] FOREIGN KEY ([ZoneId]) REFERENCES [inventory].[WarehouseZones]([ZoneId]),CONSTRAINT [FK_StockReservations_Bin] FOREIGN KEY ([BinId]) REFERENCES [inventory].[WarehouseBins]([BinId]),
    CONSTRAINT [CK_StockReservations_Quantity] CHECK ([Quantity]>0 AND [ReleasedQuantity]>=0 AND [ReleasedQuantity]<=[Quantity]),CONSTRAINT [CK_StockReservations_Status] CHECK ([Status] IN ('ACTIVE','PARTIALLY_RELEASED','RELEASED','CANCELLED'))
);
GO
CREATE INDEX [IX_StockReservations_Reference] ON [inventory].[StockReservations]([ReferenceType],[ReferenceId],[Status]);
